effect.shader:
void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    float a = radians(angle);
    vec2 n = vec2(cos(a), sin(a));
    float t = dot(acScreenNorm - 0.5, n) + 0.5 + sin(acTime) * drift;
    float leak = smoothstep(1.0 - softness, 1.0 + softness * 0.2, t);
    // Vazamento soft-light
    vec3 cor = orig.rgb + tint.rgb * leak * intensity * tint.a;
    // Toque de clareio onde a luz bate forte
    cor = mix(cor, 1.0 - (1.0 - cor) * (1.0 - tint.rgb * tint.a), leak * 0.5);
    fragColor = vec4(cor, orig.a);
}
